import manifest from "@/content/images.generated.json";

type Key = keyof typeof manifest;

/**
 * Responsive <img> for assets generated by scripts/process_images.py.
 * Always emits width/height (no CLS) and lazy-loads unless `priority`.
 */
export function Img({
  name,
  alt,
  sizes = "100vw",
  className = "",
  priority = false,
}: {
  name: string;
  alt: string;
  sizes?: string;
  className?: string;
  priority?: boolean;
}) {
  const m = manifest[name as Key];
  if (!m) return <ImageSlot label={alt} className={className} />;
  const srcSet = m.variants.map((w) => `/images/${name}-${w}.webp ${w}w`).join(", ");
  const fallback = `/images/${name}-${m.variants[Math.min(1, m.variants.length - 1)]}.webp`;
  return (
    <img
      src={fallback}
      srcSet={srcSet}
      sizes={sizes}
      width={m.width}
      height={m.height}
      alt={alt}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding="async"
      className={className}
    />
  );
}

export const imgSrc = (name: string, w = 1200) => {
  const m = manifest[name as Key];
  if (!m) return "/og-kosmex-plywood.jpg";
  const v = m.variants.filter((x) => x <= w).pop() ?? m.variants[0];
  return `/images/${name}-${v}.webp`;
};

/** Labelled placeholder for photography Kosmex has not yet supplied. */
export function ImageSlot({ label, className = "", dark = false }: { label: string; className?: string; dark?: boolean }) {
  return (
    <div
      role="img"
      aria-label={`Photo placeholder: ${label}`}
      className={`relative flex items-end overflow-hidden ${dark ? "bg-forest-3 text-mint" : "bg-ivory-2 text-muted"} ${className}`}
    >
      <svg aria-hidden className="absolute inset-0 h-full w-full opacity-[.18]" preserveAspectRatio="none" viewBox="0 0 100 100">
        <path d="M0 100 L100 0 M-20 100 L80 0 M20 100 L120 0" stroke="currentColor" strokeWidth=".3" fill="none" vectorEffect="non-scaling-stroke" />
      </svg>
      <div className="relative m-4 border border-current/30 bg-white/70 px-3 py-2 text-[.68rem] font-bold uppercase tracking-[.14em] text-forest-2 backdrop-blur-sm">
        Photo to be supplied · {label}
      </div>
    </div>
  );
}
